// watcher polls detect and reports aggregate on/off transitions through onEvent.
// It is decoupled from the clock and the hook so the loop can be driven and
// observed in tests.
type watcher struct {
	detect  func() (*camdet.Result, error)
	onEvent func(ctx context.Context, event string, res *camdet.Result)
}

// run establishes the current state and fires onEvent immediately
// (fire-on-startup), then re-detects on every receive from tick and fires
// onEvent only when the aggregate in-use state changes. It returns when ctx is
// cancelled, or with an error if a detection fails (a detection error is an
// environment precondition violation, not a transient condition).
func (w *watcher) run(ctx context.Context, tick <-chan time.Time) error {
	res, err := w.detect()
	if err != nil {
		return err
	}
	inUse := anyInUse(res)
	w.onEvent(ctx, eventFor(inUse), res)

	for {
		select {
		case <-ctx.Done():
			return nil
		case <-tick:
			res, err := w.detect()
			if err != nil {
				return err
			}
			if current := anyInUse(res); current != inUse {
				inUse = current
				w.onEvent(ctx, eventFor(current), res)
			}
		}
	}
}

